d={
'worldbuilding':[claim('血族仅能控制第一代，不能控制二代，所以列昂借萧御对抗霍尔斯；临时后裔状态最终药剂解除。',ev(342,18961,19023),ev(347,19362,19395)),claim('任务记录影响组队信任与主脑派发难度；攻城死者除特殊重生外须等战毕，王城被夺全本国玩家属性减半。',ev(357,20628,20640),ev(358,20907,20908)),claim('灵纹符把本地敌人转为有限时、削属性傀儡，副本战力随探索滚动升级。',ev(360,21447,21459),ev(361,21463,21478))],
'characters':[claim('赵由主动成为后裔帮助萧、伯爵套精神攻击破局，到现实叙述确认关系；后来公开女友称谓得到接受。',ev(342,18961,19023),ev(347,19362,19390),ev(359,21263,21279)),claim('糖果对萧的个人实力差距沮丧，但开始接受其任务判断；柠檬在萧缺席时成为实际副队长。',ev(355,20199,20200),ev(357,20626,20636),ev(358,20919,20925)),claim('风野承担成本，把个人发现转成公会转职优势，并以对刺刀之战作为精神打击计划。',ev(353,19821,19936),ev(354,20030,20059))],
'plot':[claim('伯爵套梦魇先解列昂精神控制，再成为赵杀霍尔斯的最后一击；萧的自爆是前置牺牲而非杀敌结算。',ev(345,19150,19217),ev(346,19218,19324)),claim('转职箱奖励提供隐匿与爆发能力，随后在多人国家任务中反复验证其作用。',ev(351,19590,19694),ev(355,20161,20212)),claim('城主掉的恶魔之角和抢到的天使地图把国家任务、圣言净化、梦魇旧门三个任务连续接上。',ev(357,20800,20812),ev(358,20914,20944),ev(360,21377,21386))],
'style':[claim('数值与围观反应交错给升级成果定标，如犀牛定时挑战8.76秒与群众从绝望到喝彩。',ev(359,21159,21258)),claim('战争由尸骨堆梯、箭塔和投石器的可见动作具体化；极大军团数量也扩大尺度。',ev(357,20639,20686)),claim('对兽类强迫交配使用调侃并转为坐骑奖励，文本存在把恐惧顺服浪漫化的表达；研究不复制此价值判断。',ev(358,20995,21007),ev(359,21011,21058))],
'narrative':[claim('列昂恶言之后由叙述澄清从未真想伤赵，与主角当时感知形成信息差；不能把早期威胁推断当最终动机。',ev(342,18961,18987)),claim('主角先把NPC过程当过场，又因祈求感到动容，任务视角逐渐容纳NPC情感。',ev(345,19150,19217)),claim('萧仅由墓碑同名联想萧翎可能亲属，眼前切磋没有身份确认；戒指全术能力亦为萧观察推断。',ev(354,20109,20118),ev(355,20327,20338))],
'dialogue':[claim('萧的等与短指令把任务经验转为指挥权；糖果能力抗拒逐渐让位给行动服从。',ev(357,20619,20636)),claim('风野与萧谈黑赛直接揭示相互利用和利益共生，维持萧不入公会的选择。',ev(354,20048,20055)),claim('赵明确限定性接触边界与次夜仅同房，不能把邀请推为已发生性行为。',ev(360,21359,21368))],
'pacing':[claim('索罗潜入两次等待分别被关门与满护卫阻断，再以空袭/取药调动产生行动窗口，避免全程直冲。',ev(356,20501,20516),ev(356,20596,20607),ev(357,20687,20738)),claim('刷级用回蓝、拾物、成本、敌人干扰不断引入新约束，使重复杀怪成为资源与竞争链。',ev(353,19767,19936),ev(354,19946,20059)),claim('战后净化圣言、宁静湖景形成缓冲，随后冲突转入坐骑与梦魇探索。',ev(358,20933,20949),ev(360,21377,21403))],
'themes':[claim('列昂坚持爱而拒霍尔斯的断情法则，并以牺牲完成复仇；文本承认NPC真情的价值。',ev(345,19150,19217),ev(346,19321,19324)),claim('公会优势被写成财力、地形、转职飞轮与组织竞争；主角认可胜者逻辑，但这是角色及叙述取向。',ev(354,20030,20055),ev(355,20229,20238)),claim('主角在职业受辱时反击犀牛，同时猴子以自身努力获得生计，展示游戏作为尊严与社会流动路径。',ev(359,21191,21260),ev(359,21263,21279))],
'continuity':[claim('霍尔斯/主角/赵在血族段强化与超阶标签摇摆；凤凰本次明确消耗一次，未消解前文三次/五次冲突。',ev(345,19150,19217),ev(346,19282,19324)),claim('第七城主任务又称第八、继续做第三环，环次数摇摆；后文明确守城前为完成第八、第九尚五日后。',ev(355,20404,20420),ev(358,20913,20916)),claim('暗影克制说明及对狼实测均自身控制无效，炮塔战却在开启后写凿击/迅击击晕，未解释切换。',ev(351,19590,19694),ev(355,20189,20192),ev(358,20844,20863)),claim('石魔任务称萧伯爵，而索罗系统已授侯爵；采集药方段回魔配方低/中称谓也不一。',ev(357,20793,20796),ev(361,21513,21519),ev(352,19748,19760))]
}
